/**
 * ScreenshotGrid — product captures served from /public/screenshots
 * (regenerated by scripts/screenshot.mjs) inside browser-chrome cards.
 * Clicking a card opens a lightbox: blurred backdrop, animated pop-in,
 * close via X, backdrop click, or Escape.
 */

'use client';

import { useCallback, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import Image from 'next/image';
import { Maximize2, X } from 'lucide-react';

interface Shot {
  src: string;
  title: string;
  url: string;
  caption: string;
}

const SHOTS: Shot[] = [
  {
    src: '/screenshots/dashboard.png',
    title: 'Dashboard',
    url: 'vms.local/dashboard',
    caption:
      'Stat cards, low-stock alerts, and the live activity feed — every number deep-links to the screen where you act.',
  },
  {
    src: '/screenshots/scan.png',
    title: 'Scan-first receiving',
    url: 'vms.local/scan',
    caption:
      'Camera, wedge scanner, or RFID — one scan is one action. Unknown barcodes offer to create the product.',
  },
  {
    src: '/screenshots/stock-takes.png',
    title: 'Blind stock take',
    url: 'vms.local/dashboard/stock-takes',
    caption:
      'Count what is physically there without seeing system quantities; variance posts only after review.',
  },
];

function BrowserChrome({ url }: { url: string }) {
  return (
    <div className="flex items-center gap-3 border-b border-border bg-muted/60 px-4 py-2.5">
      <span className="flex gap-1.5" aria-hidden="true">
        <span className="h-2.5 w-2.5 rounded-full bg-destructive/60" />
        <span className="h-2.5 w-2.5 rounded-full bg-muted-foreground/40" />
        <span className="h-2.5 w-2.5 rounded-full bg-primary/60" />
      </span>
      <span className="flex-1 truncate rounded-md bg-background px-3 py-1 text-xs text-muted-foreground">
        {url}
      </span>
    </div>
  );
}

export function ScreenshotGrid() {
  const [open, setOpen] = useState<Shot | null>(null);
  const [shown, setShown] = useState(false);

  const close = useCallback(() => {
    setShown(false);
    window.setTimeout(() => setOpen(null), 200);
  }, []);

  // Enter animation + Escape key + scroll lock while the lightbox is open.
  useEffect(() => {
    if (!open) return;
    const raf = requestAnimationFrame(() => setShown(true));
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    document.addEventListener('keydown', onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = prevOverflow;
    };
  }, [open, close]);

  return (
    <>
      <ul className="grid grid-cols-1 gap-6 md:grid-cols-3">
        {SHOTS.map((shot) => (
          <li key={shot.title}>
            <figure>
              <button
                type="button"
                onClick={() => setOpen(shot)}
                aria-haspopup="dialog"
                aria-label={`View ${shot.title} screenshot full size`}
                className="group block w-full cursor-zoom-in overflow-hidden rounded-xl border border-border bg-card text-left shadow-sm transition-shadow hover:shadow-md"
              >
                <BrowserChrome url={shot.url} />
                <span className="relative block aspect-[4/3]">
                  <Image
                    src={shot.src}
                    alt={`${shot.title} — VMS V0 app screenshot`}
                    fill
                    sizes="(min-width: 768px) 33vw, 100vw"
                    className="object-cover object-left-top transition-transform duration-300 group-hover:scale-[1.03]"
                  />
                  <span
                    aria-hidden="true"
                    className="absolute inset-0 flex items-center justify-center bg-black/0 opacity-0 transition-all duration-200 group-hover:bg-black/25 group-hover:opacity-100"
                  >
                    <span className="flex items-center gap-2 rounded-full bg-background/90 px-3 py-1.5 text-xs font-medium text-foreground shadow">
                      <Maximize2 className="h-3.5 w-3.5" />
                      Expand
                    </span>
                  </span>
                </span>
              </button>
              <figcaption className="mt-3">
                <p className="text-sm font-semibold">{shot.title}</p>
                <p className="mt-1 text-sm text-muted-foreground">{shot.caption}</p>
              </figcaption>
            </figure>
          </li>
        ))}
      </ul>

      {open &&
        createPortal(
          <div
            role="dialog"
            aria-modal="true"
            aria-label={`${open.title} screenshot`}
            onClick={close}
            className={`fixed inset-0 z-[100] flex items-center justify-center bg-black/60 p-4 backdrop-blur-md transition-opacity duration-200 sm:p-8 ${
              shown ? 'opacity-100' : 'opacity-0'
            }`}
          >
            <div
              onClick={(e) => e.stopPropagation()}
              className={`relative w-full max-w-5xl transition-all duration-300 ease-out ${
                shown ? 'scale-100 opacity-100' : 'scale-95 opacity-0'
              }`}
            >
              <button
                type="button"
                onClick={close}
                aria-label="Close screenshot"
                autoFocus
                className="absolute -top-12 right-0 flex h-10 w-10 items-center justify-center rounded-full bg-background/90 text-foreground shadow transition-colors hover:bg-background sm:-right-2 sm:-top-2 sm:h-9 sm:w-9"
              >
                <X className="h-5 w-5" aria-hidden="true" />
              </button>
              <div className="overflow-hidden rounded-xl border border-border bg-card shadow-2xl">
                <BrowserChrome url={open.url} />
                <div className="relative aspect-[16/10] w-full">
                  <Image
                    src={open.src}
                    alt={`${open.title} — VMS V0 app screenshot`}
                    fill
                    sizes="(min-width: 1024px) 80vw, 100vw"
                    className="object-contain"
                    priority
                  />
                </div>
              </div>
              <div className="mt-4 text-center">
                <p className="text-sm font-semibold text-white">{open.title}</p>
                <p className="mt-1 text-sm text-white/70">{open.caption}</p>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </>
  );
}
